/// OpenSSL enum `X509_LOOKUP_TYPE`. Manual: https://docs.openssl.org/3.5/man3/X509_LOOKUP/
enum X509_LOOKUP_TYPE {
  X509_LU_NONE(0),
  X509_LU_X509(1),
  X509_LU_CRL(2);

  final int value;
  const X509_LOOKUP_TYPE(this.value);

  static X509_LOOKUP_TYPE fromValue(int value) => switch (value) {
    0 => X509_LU_NONE,
    1 => X509_LU_X509,
    2 => X509_LU_CRL,
    _ => throw ArgumentError('Unknown value for X509_LOOKUP_TYPE: $value'),
  };
}

